class Account:
    def __init__(self, owner):
        self.owner = owner
        self._balance = 0

    def deposit(self, amount):
        if amount <= 0:
            return "Amount must be positive"
        self._balance += amount
        return "OK"

    @property
    def balance(self):
        return self._balance

acc = Account("Ravi")
print(acc.deposit(500), acc.deposit(-100))
print(acc.balance)

